def card(work):
    sr = 22050
    classes = {'ui': -20, 'small': -16, 'normal': -12, 'big': -9}

    def synth(preset, pitch, length, seed, style):
        rng = np.random.default_rng(seed)
        n = int(length * sr)
        t = np.arange(n) / sr
        f = 440 * 2 ** (pitch / 12)
        if preset == 'coin':
            x = np.sin(2 * np.pi * f * t * (1 + (t > 0.05)))
        elif preset == 'hit':
            x = rng.standard_normal(n)
        else:
            x = np.sin(2 * np.pi * f * t)
        x *= np.exp(-t / (length / 3))
        if style == 'retro':
            x = np.sign(x) * np.abs(x)
        return x

    def peak50_db(x):
        w = int(0.05 * sr)
        return max((10 * np.log10(np.mean(x[i:i + w] ** 2) + 1e-12) for i in range(0, max(1, len(x) - w), w // 2)))

    def normalise(x, cls):
        g = 10 ** ((classes[cls] - peak50_db(x)) / 20)
        y = x * g
        pk = np.abs(y).max()
        return y * min(1.0, 10 ** (-1 / 20) / pk) if pk else y

    def warnings(x, f0):
        w = []
        onset = np.argmax(np.abs(x) > 0.1 * np.abs(x).max()) / sr
        if onset > 0.02:
            w.append(f'late onset {onset:.3f}s')
        if f0 < 80:
            w.append('inaudible lows on phones')
        return w
    spec = [('coin', 'coin', 12, 0.2, 'clean', 'small', 3), ('hit', 'hit', 0, 0.15, 'retro', 'normal', 3), ('win', 'tone', 0, 0.6, 'soft', 'big', 1)]
    out = {}
    for name, preset, pitch, L, style, cls, nvar in spec:
        out[name] = []
        for v in range(nvar):
            y = normalise(synth(preset, pitch, L, 100 + v, style), cls)
            write_wav(work / f'{name}_{v}.wav', y, sr)
            out[name].append(round(peak50_db(y), 2))
    late = np.concatenate([np.zeros(int(0.1 * sr)), synth('tone', 0, 0.2, 1, 'clean')])
    low = synth('tone', -36, 0.3, 1, 'clean')
    jwrite(work, 'sfx_manifest.json', out)
    pk = max(np.abs(read_wav(work / 'hit_0.wav')[0]).max(), 1e-09)
    return [chk('3 variants for frequent sounds, 1 for a one-off', len(out['coin']) == 3 and len(out['win']) == 1, out), chk('small class at -16 dB (loudest 50 ms)', all((near(v, -16, 0.6) for v in out['coin'])), out['coin']), chk('ceiling -1 dBFS respected', 20 * math.log10(pk) <= -0.9, round(20 * math.log10(pk), 2)), chk('late onset warned', any(('late onset' in w for w in warnings(late, 440))), warnings(late, 440)), chk('55 Hz effect warned as inaudible low', warnings(low, 440 * 2 ** (-3)) == ['inaudible lows on phones'], warnings(low, 55))]

def card(work):
    lyrics = '[Verse]\nنمشي على درب القمر\n[Verse]\nوالليل يحكي ما استتر\n[Bridge]\nيا قلب لا تخشى السفر\n[Verse]\nنرجع ومعنا المطر'
    style = {'genre': 'arabic pop', 'mood': 'hopeful', 'instruments': 'oud, strings, soft drums', 'tempo': '92 bpm'}

    def sections(text):
        return [l.strip()[1:-1].lower() for l in text.splitlines() if l.strip().startswith('[')]

    def form(secs):
        m = {'verse': 'A', 'chorus': 'B', 'refrain': 'R', 'bridge': 'B'}
        code = ''.join((m.get(s, '?') for s in secs))
        if code == 'AABA':
            return 'AABA'
        if 'verse' in secs and 'chorus' in secs:
            return 'verse/chorus'
        if all((s in ('verse', 'refrain') for s in secs)):
            return 'verse/refrain'
        return 'unknown'

    def style_prompt(st):
        p = ', '.join((st[k] for k in ('genre', 'mood', 'instruments', 'tempo')))
        return p if len(p) <= 120 else None
    secs = sections(lyrics)
    vc = sections('[Verse]\nx\n[Chorus]\ny\n[Verse]\nz\n[Chorus]\nw')
    prompt = style_prompt(style)
    (work / 'suno_prompt.txt').write_text(prompt + '\n\n' + lyrics + '\n', encoding='utf-8')
    return [chk('sections tagged and read in order', secs == ['verse', 'verse', 'bridge', 'verse'], secs), chk('form recognised as AABA', form(secs) == 'AABA', form(secs)), chk('verse/chorus recognised', form(vc) == 'verse/chorus', form(vc)), chk('compact style prompt has genre, mood, instruments, tempo', prompt and prompt.count(',') >= 3 and ('92 bpm' in prompt), prompt)]

