        codec = 'mulaw' if sr == 8000 else 'pcm16'
        stt = 'telephony-8k' if sr == 8000 else 'wideband'
        if 'ar' in languages and 'ar' not in {'telephony-8k': ['en', 'ar', 'es'], 'wideband': ['en', 'ar', 'fr']}[stt]:
