    a, b = (choose('pstn', ['ar'], True), choose('web', ['en', 'ar'], False))
    jwrite(work, 'stack.json', {'pstn': a, 'web': b})
    return [chk('telephony -> 8 kHz mu-law narrowband model', a['sample_rate'] == 8000 and a['codec'] == 'mulaw', a), chk('web -> 16 kHz wideband', b['sample_rate'] == 16000 and b['stt_model'] == 'wideband', b), chk('barge-in only with streaming', a['barge_in'] and (not b['barge_in']), (a['barge_in'], b['barge_in']))]

def card(work):

    def choose(change):
        table = [('same_item_deeper', 'shared-element'), ('data_loaded', 'suspense-reveal'), ('list_reorder', 'per-item-key'), ('appear', 'enter-exit'), ('disappear', 'enter-exit'), ('tab_switch', 'fade-or-none'), ('background_refresh', 'none'), ('route_change', 'route-level')]
        return dict(table).get(change, 'none')

    def nav_type(from_depth, to_depth):
        return 'nav-forward' if to_depth > from_depth else 'nav-back' if to_depth < from_depth else None
    cases = {'same_item_deeper': 'shared-element', 'data_loaded': 'suspense-reveal', 'list_reorder': 'per-item-key', 'tab_switch': 'fade-or-none', 'background_refresh': 'none'}
    got = {k: choose(k) for k in cases}
    jwrite(work, 'transitions.json', got)
    return [chk(f'{k} -> {v}', got[k] == v, got[k]) for k, v in cases.items()] + [chk('hierarchy depth gives nav-forward/nav-back', (nav_type(1, 2), nav_type(2, 1)) == ('nav-forward', 'nav-back'), 'typed')]

def card(work):

    def check(title, thumb, intent):
        errs = []
        tw = {w.lower().strip('.,!?') for w in title.split()}
        rep = [w for w in thumb.split() if w.lower().strip('.,!?') in tw]
        if rep:
            errs.append(f'thumbnail repeats title word(s): {rep}')
        if len(title) > 60:
            errs.append('title > 60 chars')
        if not 1 <= len(thumb.split()) <= 3:
            errs.append('thumbnail text must be 1-3 words')
        if intent == 'search' and (not title.lower().startswith(('how to', 'best', 'كيف'))):
            errs.append('search intent: front-load the query phrase')
        return errs
    good = check('How to fix a slow laptop in 10 minutes', 'STILL LAGGING?', 'search')
    bad = check('This laptop trick will change your life forever and ever, really', 'laptop trick here now', 'search')
    jwrite(work, 'packaging.json', {'good': good, 'bad': bad})
    return [chk('good pair passes', good == [], good), chk('repeated word caught', any(('repeats' in e for e in bad)), bad), chk('>60 char title and 4-word thumbnail caught', 'title > 60 chars' in bad and 'thumbnail text must be 1-3 words' in bad, bad), chk('search title must front-load the query', any(('front-load' in e for e in bad)), bad)]
